// Personal SignM pipeline: prepares drafts and records manual sales stages.
// Sending remains in OwnerInbox, with its own explicit recipient confirmation.
'use strict';
window.SignMPipeline = (() => {
  let data=null, detail=null, selected=0, busy=false, loading=false, error='', notice='', epoch=0, showStage='all';
  let openConversation=null,copySelection=false;
  const forms=new Map();
  const stages={new:'Новый запрос',reviewed:'Проверен',draft:'Черновик готов',contacted:'Написал',replied:'Получен ответ',qualified:'Задача уточнена',proposal:'Предложение',payment_pending:'Ожидаем оплату',paid:'Оплата отмечена',lost:'Закрыт без сделки'};
  const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const date=v=>v?new Date(v).toLocaleString('ru-RU'):'—';
  const money=v=>Number(v||0).toLocaleString('ru-RU',{maximumFractionDigits:4});
  const root=()=>document.querySelector('#signm-pipeline');
  const button=(label,action,id='',disabled=false)=>`<button type="button" class="button secondary" data-sp-action="${action}" data-id="${h(id)}" ${disabled||busy?'disabled':''}>${h(label)}</button>`;
  const field=(name,label,value='',extra='')=>`<label class="ls-field">${h(label)}<input name="${name}" value="${h(value)}" ${extra}></label>`;
  const area=(name,label,value='',max=8000)=>`<label class="ls-field">${h(label)}<textarea name="${name}" rows="5" maxlength="${max}">${h(value)}</textarea></label>`;
  const check=(name,label,value=false)=>`<label class="ls-check"><input type="checkbox" name="${name}" ${value?'checked':''}>${h(label)}</label>`;
  const link=v=>/^https:\/\/t\.me\//i.test(v||'')?`<a class="button secondary" href="${h(v)}" target="_blank" rel="noopener noreferrer">Исходное сообщение</a>`:'';
  const qualified=item=>item.qualification?.label==='direct_request';
  const contactable=item=>item.contact?.kind==='telegram_author';
  const ready=item=>qualified(item)&&contactable(item)&&item.fresh===true&&item.eligible===true;
  const senderReady=sender=>sender?.connected===true&&Number(sender.account_id)===710000010;
  const enumLabel={direct_request:'Запрос заказчика',supplier_offer:'Предложение исполнителя',employment:'Вакансия / поиск работы',aggregator:'Репост / агрегатор',unclear:'Нужно проверить'};
  const geoLabel={dubai:'Дубай',other:'Другая география',unknown:'Не подтверждена',unspecified:'Не указана'};
  const scopeLabel={dubai:'Дубай / ОАЭ',any:'Любая география'};
  const currentScope=()=>data?.settings?.geo_scope==='any'?'any':'dubai';
  const itemScope=item=>['dubai','any'].includes(item.geo_scope)?item.geo_scope:currentScope();
  const reasonLabel={explicit_service_request:'Есть прямой запрос по услуге. Формат и актуальность нужно уточнить.'};
  const qualificationReason=(item,fallback)=>{const reason=String(item.qualification?.reason||'');return reasonLabel[reason]||(/^[a-z]+(?:_[a-z0-9]+)+$/.test(reason)?'Основание нужно проверить вручную':reason||fallback);};
  async function api(path='',body){
    const response=await fetch('/api/scanner/marketing/pipeline'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Scanner-Request':'1'},signal:AbortSignal.timeout(45000),...(body===undefined?{}:{body:JSON.stringify(body)})});
    let result;try{result=await response.json();}catch{throw Error('Сервис не ответил. Сохранённые поля остаются в форме; обновите результат.');}
    if(!response.ok){const failure=Error(typeof result.detail==='string'?result.detail:'Не удалось выполнить действие. Проверьте поля.');failure.status=response.status;throw failure;}return result;
  }
  function view(){return '<div id="signm-pipeline"><div class="empty"><strong>Загружаем путь от запроса до оплаты…</strong></div></div>';}
  async function mount(options={}){if(options.openConversation)openConversation=options.openConversation;if(data||error)render();await reload();}
  async function reload(){
    const version=++epoch;loading=true;
    try{const next=await api();if(version!==epoch)return;const nextDetail=selected?((next.items||[]).find(x=>Number(x.lead_id)===selected)||await api('/'+selected)):null;if(version!==epoch)return;data=next;detail=nextDetail;error='';}
    catch(e){if(version!==epoch)return;error=e.message;if([401,403].includes(e.status)){data=null;detail=null;forms.clear();}}
    finally{if(version===epoch){loading=false;render();}}
  }
  async function open(leadId){selected=Number(leadId);if(!selected)return;const version=++epoch;loading=true;
    try{const nextDetail=await api('/'+selected);if(version!==epoch)return;const nextData=data||await api();if(version!==epoch)return;detail=nextDetail;data=nextData;error='';}
    catch(e){if(version!==epoch)return;error=e.message;if([401,403].includes(e.status)){data=null;detail=null;forms.clear();}}
    finally{if(version===epoch){loading=false;render();root()?.querySelector('[data-sp-detail]')?.scrollIntoView({block:'start'});}}
  }
  function key(form){return form.dataset.spForm==='settings'?'settings':form.dataset.spForm+':'+form.dataset.id;}
  function remember(form){if(!form?.matches('[data-sp-form]'))return;forms.set(key(form),Object.fromEntries([...form.elements].filter(x=>x.name).map(x=>[x.name,x.type==='checkbox'?x.checked:x.value])));}
  function restore(){root()?.querySelectorAll('[data-sp-form]').forEach(form=>{const saved=forms.get(key(form));if(!saved)return;for(const el of form.elements)if(Object.hasOwn(saved,el.name)){if(el.type==='checkbox')el.checked=saved[el.name];else el.value=saved[el.name];}});}
  function reviewReason(item){return [item.fresh===false?'Запрос старше выбранного периода':'',item.eligible===false&&qualified(item)&&contactable(item)&&item.fresh===true?(item.geo_allowed===false?'Не соответствует выбранной географии: '+scopeLabel[item.geo_scope==='any'?'any':'dubai']:'Нет подтверждённого исходного запроса'):'',!qualified(item)?(enumLabel[item.qualification?.label]||'Намерение заказать не подтверждено'):'',!contactable(item)?(item.contact?.reason||'Нет проверенного личного контакта'):''].filter(Boolean).join(' · ');}
  function card(item,excluded=false){const services=Array.isArray(item.qualification?.services)?item.qualification.services:[];
    return `<article class="ls-lead sp-card"><div class="ls-lead-head"><strong>${h(item.source_title||'Источник не указан')}</strong><time>${h(date(item.created))}</time></div><p>${h(item.author||'Автор не указан')} · ${h(stages[item.stage]||stages.new)}${item.source_geo?' · '+h(geoLabel[item.source_geo]||item.source_geo):''}</p>${excluded?`<p class="notice amber small">${h(reviewReason(item))}</p>`:''}<p class="ls-message">${h(item.text)}</p><p class="small muted">${h(qualificationReason(item,'Требует проверки'))}${services.length?' · '+h(services.join(', ')):''}</p><div class="ls-actions">${button('Разобрать запрос','open',item.lead_id)}${link(item.link)}</div></article>`;
  }
  function settingsView(){const cfg=data.settings||{},ai=data.ai||{},budget=data.budget||{};
    return `<details class="sp-settings"><summary>География, черновики, ИИ и реквизиты</summary><p>Шаблоны формируются без платного API. Они сохраняются в панели и проходят вашу проверку. Автоматическая отправка первого сообщения не включается.</p><form data-sp-form="settings">${check('auto_templates','Готовить шаблоны для новых подходящих запросов',cfg.auto_templates)}<label class="ls-field">География поиска<select name="geo_scope" required>${Object.entries(scopeLabel).map(([value,label])=>`<option value="${value}" ${value===(cfg.geo_scope||'dubai')?'selected':''}>${h(label)}</option>`).join('')}</select></label><p class="small muted">Фильтр применяется к сохранённым находкам. Новые чаты сами не подключаются; проверенный профиль источников относится к Дубаю.</p><div class="ls-columns">${field('days','Свежесть запроса, дней',cfg.days??7,'type="number" min="1" max="7" required')}${field('max_templates_per_day','До новых шаблонов в сутки',cfg.max_templates_per_day??10,'type="number" min="1" max="50" required')}</div>${area('payment_instructions','Как клиент может оплатить услугу',cfg.payment_instructions||'',1500)}<p class="small muted">Укажите только предназначенные клиенту реквизиты или ссылку на оплату. Получение денег отмечается отдельно по фактическому платежу.</p><h3>Платный черновик ИИ</h3><p>${ai.key_configured?'Ключ сохранён':'Ключ не подключён'} · ${ai.provider_verified?'Провайдер проверен':'Провайдер не проверен'}${ai.model?' · '+h(ai.model):''}. ${ai.paused?'Автоматические ответы на паузе.':''}</p><p>Расчётный лимит на черновики: $${money(budget.limit_usd??cfg.ai_budget_usd)} · зарезервировано: $${money(budget.reserved_usd)} · потрачено: $${money(budget.spent_usd)}.</p><p class="small muted">Ключ и модель настраиваются в «Переписке → Настройки ИИ». Черновик ИИ создаётся только отдельной кнопкой после подтверждения расхода.</p><div class="ls-columns">${field('ai_budget_usd','Расчётный бюджет генерации черновиков, USD',cfg.ai_budget_usd??0,'type="number" min="0" max="100" step="0.01" required')}${field('input_usd_per_million','Цена 1 млн входных токенов, USD',cfg.input_usd_per_million??0,'type="number" min="0" max="1000" step="0.0001" required')}${field('output_usd_per_million','Цена 1 млн выходных токенов, USD',cfg.output_usd_per_million??0,'type="number" min="0" max="1000" step="0.0001" required')}</div><p class="small muted">Бюджет относится к генерации черновиков; тарифы берутся из кабинета провайдера. Проверка ключа и автоответы учитываются отдельно. Это расчётный предел в панели, а не баланс API-провайдера. Нулевой бюджет выключает платные черновики.</p><button class="button" ${busy?'disabled':''}>Сохранить настройки</button></form></details>`;
  }
  function detailView(item){const lid=Number(item.lead_id),ai=data.ai||{},budget=data.budget||{},eligible=ready(item),sender=data.sender||{};
    const canAI=eligible&&ai.key_configured&&ai.provider_verified&&ai.consent&&Number(data.settings?.input_usd_per_million)>0&&Number(data.settings?.output_usd_per_million)>0&&Number(budget.limit_usd??data.settings?.ai_budget_usd)>Number(budget.spent_usd||0)+Number(budget.reserved_usd||0);
    return `<section class="panel ls-section sp-detail" data-sp-detail><div class="panel-head"><div><h2>Запрос №${lid}: ${h(stages[item.stage]||stages.new)}</h2><p>${h(item.author||'Автор не указан')} · ${h(item.source_title||'Источник не указан')}</p></div>${button('Закрыть карточку','close')}</div><p class="ls-message">${h(item.text)}</p><p>${link(item.link)}</p><div class="notice sp-qualification"><strong>${h(enumLabel[item.qualification?.label]||'Квалификация требует проверки')}</strong><p>${h(qualificationReason(item,'Причина не указана'))}</p>${item.qualification?.evidence?`<p>Основание: «${h(Array.isArray(item.qualification.evidence)?item.qualification.evidence.join(' · '):item.qualification.evidence)}»</p>`:''}<p>Контакт: ${h(item.contact?.contact_username?'@'+item.contact.contact_username:item.contact?.reason||'Не подтверждён')}</p><p>Выбранная география: ${h(scopeLabel[itemScope(item)])}. География запроса: ${h(geoLabel[item.request_geo]||'Не подтверждена')}. Источник: ${h(geoLabel[item.source_geo]||'Не определён')}. Участие в чате о Дубае не подтверждает место проживания.</p></div>${!eligible?`<p class="ls-error">${h(reviewReason(item))}. Подготовка первого отклика недоступна.</p>`:''}<form data-sp-form="draft" data-id="${lid}">${area('text','Черновик отклика — редактируется до отправки',item.draft||'',1200)}<p class="small muted">${h({template:'Подготовлен шаблон',ai:'Создан ИИ',manual:'Отредактирован вручную'}[item.draft_kind]||'Черновик ещё не подготовлен')}. Сохранение и копирование ничего не отправляют в Telegram.</p><div class="ls-actions"><button class="button secondary" ${busy||!eligible?'disabled':''}>Сохранить черновик</button>${button('Скопировать текст','copy',lid,false)}${button(item.draft||forms.get('draft:'+lid)?.text?'Открыть переписку с черновиком':'Открыть переписку','conversation',lid,!eligible||!senderReady(sender))}</div></form><form data-sp-form="ai" data-id="${lid}">${check('confirmed','Разрешаю один платный запрос ИИ с текстом этого лида; отправки в Telegram не будет')}<button class="button secondary" ${busy||!canAI?'disabled':''}>Подготовить черновик ИИ</button>${!canAI?'<p class="small muted">Нужны подходящий свежий запрос, проверенный API и доступный бюджет.</p>':''}</form><h3>Продвижение к оплате</h3><form data-sp-form="stage" data-id="${lid}"><label class="ls-field">Этап<select name="stage">${Object.entries(stages).map(([value,label])=>`<option value="${value}" ${value===(item.stage||'new')?'selected':''} ${['new','draft'].includes(value)?'disabled':''}>${h(label)}</option>`).join('')}</select></label><p class="small muted">Для этапов «Написал» и «Получен ответ» сервер проверяет сохранённую отправку или входящее сообщение в переписке. Без такой истории этап не сохранится.</p><div class="ls-columns">${field('amount','Сумма сделки',item.amount||'','type="number" min="0.01" step="0.01"')}
      <label class="ls-field">Валюта<select name="currency">${['USD','RUB','AED'].map(c=>`<option ${c===(item.currency||'USD')?'selected':''}>${c}</option>`).join('')}</select></label></div>${field('payment_reference','Номер платежа / ссылка на подтверждение',item.payment_reference||'','maxlength="500"')}${check('confirmed','Если отмечаю оплату: деньги фактически получены, сумма и подтверждение проверены мной')}<p class="small muted">«Оплата отмечена» — ваша ручная запись о получении денег. Банк и платёжная система автоматически её не проверяют.${item.payment_verified_at?' Отмечено владельцем: '+h(date(item.payment_verified_at))+'.':''}</p><button class="button secondary" ${busy?'disabled':''}>Сохранить этап</button></form>${data.settings?.payment_instructions?`<details><summary>Инструкция по оплате для клиента</summary><p class="ls-message">${h(data.settings.payment_instructions)}</p></details>`:''}</section>`;
  }
  function render(){const el=root();if(!el)return;if(!data){el.innerHTML=`${error?`<div class="ls-error" role="alert">${h(error)}</div>`:''}${button('Повторить загрузку','refresh')}`;return;}
    const items=data.items||[],main=items.filter(ready),excluded=items.filter(x=>!ready(x));
    const visible=main.filter(x=>showStage==='all'||(x.stage||'new')===showStage);
    const paid=items.filter(x=>x.stage==='paid'&&Number(x.amount)>0&&x.payment_reference&&x.payment_verified_at).length;
    const sender=data.sender||{};
    el.innerHTML=`<section class="panel ls-section"><div class="panel-head"><div><h2>Лиды → отклик → диалог → оплата</h2><p>Сайты, SEO, Директ, SMM и автоматизация · ${h(scopeLabel[currentScope()])} · русский и английский</p></div>${button('Обновить','refresh')}</div>${error?`<div class="ls-error" role="alert">${h(error)}</div>`:''}${notice?`<div class="notice" role="status">${h(notice)}</div>`:''}<div class="sp-summary"><span><strong>${main.length}</strong> свежих запросов с контактом</span><span><strong>${excluded.length}</strong> требуют проверки / исключены</span><span><strong>${paid}</strong> оплат отмечено с подтверждением</span></div><p class="small muted">Подключено источников: ${Number(data.source_count||0)}. ${h(data.source_profile?.note||'Показана текущая выборка запросов.')}. Найденный запрос ещё не означает интерес к SignM или продажу.</p><div class="notice">Переписка: ${h(sender.username?'@'+String(sender.username).replace(/^@/,''):'личный аккаунт не подключён')} · ID ${h(sender.account_id||'—')}. Ожидаемый отправитель — @demo_identity_3, ID 710000010.${!senderReady(sender)?' Переписка недоступна до подключения нужной сессии.':''} Первый отклик проверяется и отправляется вручную из «Переписки»; массовой отправки здесь нет.</div>${settingsView()}<div class="ls-actions">${button('Подготовить до 10 шаблонов','prepare')}
      <label>Этап <select data-sp-filter><option value="all">Все этапы</option>${Object.entries(stages).map(([value,label])=>`<option value="${value}" ${value===showStage?'selected':''}>${h(label)}</option>`).join('')}</select></label></div></section>${detail?detailView(detail):''}<section class="panel ls-section"><h2>Подходящие запросы</h2>${visible.length?visible.map(item=>card(item)).join(''):'<div class="empty"><strong>Подходящих запросов пока нет</strong>Проверьте источники, свежесть и правила поиска. Предложения исполнителей и репосты без контакта находятся ниже.</div>'}</section>${excluded.length?`<section class="panel ls-section"><details><summary>Отдельно: исполнители, биржи, старые записи и неподтверждённые контакты (${excluded.length})</summary>${excluded.map(item=>card(item,true)).join('')}</details></section>`:''}`;restore();if(copySelection){const textarea=el.querySelector('[data-sp-form="draft"] textarea');textarea?.focus();textarea?.select();copySelection=false;}
  }
  async function action(fn){if(busy)return;busy=true;error='';notice='';render();try{await fn();}catch(e){error=e.message;}finally{busy=false;render();}}
  async function copy(lid){const text=forms.get('draft:'+lid)?.text??detail?.draft??'';if(!text.trim())throw Error('Сначала подготовьте или напишите черновик.');try{await navigator.clipboard.writeText(text);notice='Черновик скопирован. Проверьте получателя перед отправкой.';}catch{copySelection=true;notice='Автокопирование недоступно. Текст выделен — скопируйте его вручную.';}}
  document.addEventListener('input',event=>remember(event.target.closest('[data-sp-form]')));
  document.addEventListener('change',event=>{remember(event.target.closest('[data-sp-form]'));if(event.target.matches('[data-sp-filter]')){showStage=event.target.value;render();}});
  document.addEventListener('click',event=>{const el=event.target.closest('[data-sp-action]');if(!el||!root())return;const a=el.dataset.spAction,lid=Number(el.dataset.id);if(busy)return;
    if(a==='open'){open(lid);return;}if(a==='close'){detail=null;selected=0;render();return;}
    action(async()=>{if(a==='refresh'){await reload();return;}if(a==='prepare'){const result=await api('/prepare',{limit:10});await reload();notice='Подготовлено новых шаблонов: '+Number(result.count||0)+'. Личные сообщения не отправлялись.';}if(a==='copy')await copy(lid);if(a==='conversation'){if(openConversation)await openConversation(lid,forms.get('draft:'+lid)?.text??detail?.draft??'');else throw Error('Откройте вкладку «Переписка» из раздела SignM.');}});
  });
  document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-sp-form]'))return;event.preventDefault();if(busy)return;remember(form);const formKey=key(form),fd=new FormData(form),get=name=>String(fd.get(name)||'').trim(),lid=Number(form.dataset.id);
    action(async()=>{
      if(form.dataset.spForm==='settings')await api('/settings',{auto_templates:fd.has('auto_templates'),geo_scope:get('geo_scope'),days:Number(get('days')),max_templates_per_day:Number(get('max_templates_per_day')),payment_instructions:get('payment_instructions'),ai_budget_usd:Number(get('ai_budget_usd')),input_usd_per_million:Number(get('input_usd_per_million')),output_usd_per_million:Number(get('output_usd_per_million'))});
      if(form.dataset.spForm==='draft')await api('/'+lid+'/draft',{text:get('text')});
      if(form.dataset.spForm==='stage'){
        if(['new','draft'].includes(get('stage')))throw Error('Выберите следующий этап.');
        if(get('stage')==='paid'&&!['proposal','payment_pending','paid'].includes(detail?.stage))throw Error('Сначала сохраните предложение или ожидание оплаты.');
        if(get('stage')==='paid'&&(!(Number(get('amount'))>0)||get('payment_reference').length<6||!fd.has('confirmed')))throw Error('Для отметки оплаты укажите положительную сумму и подтверждение платежа, затем подтвердите фактическое получение денег.');
        await api('/'+lid+'/stage',{stage:get('stage'),amount:get('amount'),currency:get('currency'),payment_reference:get('payment_reference'),confirmed:fd.has('confirmed')});
      }
      if(form.dataset.spForm==='ai'){if(!fd.has('confirmed'))throw Error('Подтвердите один платный запрос ИИ.');await api('/'+lid+'/ai-draft',{confirmed:true});}
      forms.delete(formKey);await reload();notice=form.dataset.spForm==='stage'&&get('stage')==='paid'?'Получение оплаты отмечено вами вручную.':'Изменения сохранены. Отправки в Telegram не было.';
    });
  });
  setInterval(()=>{const el=root();if(el&&document.visibilityState!=='hidden'&&!busy&&!loading&&!el.contains(document.activeElement))reload();},15000);
  return {view,mount,open};
})();
